export function resourcesPage() {
  const categories = [...new Set(resources.map(([category]) => category))];
  return `<section class="page resource-page"><button class="text-button" id="resources-back">← К курсу</button>
    <h1 tabindex="-1">После курса</h1>
    <p class="lead">Бесплатные инструменты и задания на 10–20 минут, чтобы продолжить изучать ИИ.</p>
    <section class="lab-panel"><h2>Маршрут из четырёх шагов</h2><ol>
    ${route.map(([name, tool, result]) => `<li><b>${name}</b> · ${tool}. ${result}</li>`).join('')}
    </ol></section>
    <p class="muted">Условия сверены 11 ноября 2026 года. Доступ к зарубежным сайтам из России отдельно не проверен. В заданиях используй вымышленные данные и снимки предметов без лиц.</p>
    ${categories.map(category => `<section><h2>${category}</h2><div class="resource-grid">
      ${resources.filter(item => item[0] === category).map(([, name, url, summary, task, access]) => `
        <article class="lab-panel"><h3><a href="${url}" target="_blank" rel="noopener noreferrer">${name} ↗</a></h3>
        <p>${summary}</p><p><b>Попробуй.</b> ${task}</p><p class="muted">${access}</p>${help[name] ? `<p><a href="${help[name]}" target="_blank" rel="noopener noreferrer">Официальные условия и справка ↗</a></p>` : ''}</article>`).join('')}
    </div></section>`).join('')}
  </section>`;
}
